namespace sv_7e689e3840b54cb88971956a11f486fd.Services;

public sealed class RecipeService
{
    private static readonly List<Recipe> SeedData =
    [
        // Cuisine 1: Italian
        new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, pecorino, guanciale, and black pepper.", 25),
        new(2, "Margherita Pizza", "Traditional Neapolitan pizza with tomato, mozzarella, and fresh basil.", 45),
        new(3, "Risotto al Funghi", "Creamy Arborio rice cooked with porcini mushrooms and Parmigiano.", 35),
        new(4, "Tiramisu", "Layered dessert with espresso-soaked ladyfingers and mascarpone cream.", 30),

        // Cuisine 2: Japanese
        new(5, "Tonkotsu Ramen", "Rich pork bone broth with chashu, soft egg, and fresh noodles.", 480),
        new(6, "Chicken Katsu Curry", "Crispy panko-breaded chicken with Japanese curry sauce and rice.", 40),
        new(7, "Miso Soup", "Dashi broth with white miso, silken tofu, and wakame seaweed.", 15),
        new(8, "Gyoza", "Pan-fried pork and cabbage dumplings with dipping sauce.", 50),

        // Cuisine 3: Mexican
        new(9, "Tacos al Pastor", "Marinated pork tacos with pineapple, onion, and cilantro.", 60),
        new(10, "Chicken Enchiladas", "Corn tortillas filled with chicken and smothered in red sauce and cheese.", 45),
        new(11, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
        new(12, "Churros", "Fried dough pastry coated in cinnamon sugar with chocolate sauce.", 35),
    ];

    private static readonly Dictionary<int, List<Recipe>> ByCuisine = SeedData
        .GroupBy(r => r.Id switch
        {
            >= 1 and <= 4 => 1,
            >= 5 and <= 8 => 2,
            _ => 3
        })
        .ToDictionary(g => g.Key, g => g.ToList());

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow backend API call
        await Task.Delay(2000, cancellationToken);

        if (ByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return [];
    }
}

public sealed record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_7e689e3840b54cb88971956a11f486fd.Services
@inject RecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p class="text-muted"><small>Refreshing…</small></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    private IEnumerable<Recipe> DisplayedRecipes => Sort?.ToLowerInvariant() switch
    {
        "newest" => _recipes!.OrderByDescending(r => r.Id),
        "popular" => _recipes!.OrderBy(r => r.PrepTimeMinutes),
        _ => _recipes!
    };

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync();
        }
        // Sort changed — no reload needed, re-render handles it
        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }
        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);

        _isRefreshing = _recipes is not null;
        _error = null;
        _loadedCuisineId = CuisineId;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, _loadCts.Token);
            _recipes = results;
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (_disposeCts.IsCancellationRequested)
        {
            // Component is disposing — do nothing
        }
        catch (OperationCanceledException)
        {
            // Superseded by a newer load — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "The request timed out. Please try again.";
            _isRefreshing = false;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "Something went wrong while loading recipes. Please try again.";
            _isRefreshing = false;
        }
    }

    private Task Retry() => LoadRecipesAsync();

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

